import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';

const messages = defineMessages({
  positionLabel: {
    id: 'slide_indicator.position.label',
    defaultMessage: 'Image {current} of {total}',
  },
});

const ZIMM_SLIDE_INDICATOR_RECIPE = 'ZimmSlideIndicator';

type ZimmSlideIndicatorProps = {
  /** Total number of images/slides the strip represents. */
  count: number;
  /** Index (0-based) of the currently active/visible slide. Out-of-range values are clamped. */
  activeIndex: number;
};

/**
 * Molecule — read-only image-position indicator for touch devices (tablet + mobile) on the
 * PDP/card image strip. Figma node 40002536:7957 ("Slide indicator"): a segmented 1px hairline
 * strip, one segment per image, the active segment picked out by colour. NOT floating dots.
 *
 * Touch-only per the resolved arrows-vs-indicator split (SFCC-236): hover-capable pointers get
 * prev/next arrow buttons instead (a separate component) and never render this molecule.
 * Because no arrows exist wherever this DOES render, it is the *sole* position signal
 * available there — the root is exposed (`role="group"` + a computed `aria-label`), never
 * `aria-hidden`, while the individual segments are purely decorative (`aria-hidden`) so
 * assistive tech announces the position once via the group label, not once per segment.
 *
 * Renders nothing for `count <= 1` — a single image has no position to indicate among.
 */
export const ZimmSlideIndicator = ({ count, activeIndex }: ZimmSlideIndicatorProps) => {
  const intl = useIntl();

  // Out-of-range clamps rather than throwing: activeIndex < 0 treats as the first slide,
  // activeIndex >= count treats as the last. Written explicitly rather than relying on
  // Array.map/index lookups to silently no-op on an out-of-range value.
  const clampedIndex = Math.min(Math.max(activeIndex, 0), count - 1);

  // Two static resolutions (isActive: false / true), not one per rendered segment — calling
  // useMultiStyleConfig inside the render loop below would be a conditional/looped hook call.
  // Which of the two resolved objects applies to a given segment is picked per-element in the
  // map below instead.
  const styles = useMultiStyleConfig(ZIMM_SLIDE_INDICATOR_RECIPE, { isActive: false });
  const activeStyles = useMultiStyleConfig(ZIMM_SLIDE_INDICATOR_RECIPE, { isActive: true });

  // A single image has nothing to indicate a position among.
  if (count <= 1) return null;

  const label = intl.formatMessage(messages.positionLabel, {
    current: clampedIndex + 1,
    total: count,
  });

  return (
    <chakra.div role="group" aria-label={label} __css={styles.root}>
      {Array.from({ length: count }, (_, i) => {
        const isActive = i === clampedIndex;
        return (
          <chakra.div
            key={i}
            aria-hidden
            data-active={isActive ? 'true' : undefined}
            __css={isActive ? activeStyles.dot : styles.dot}
          />
        );
      })}
    </chakra.div>
  );
};

export default ZimmSlideIndicator;
